 oldnames={r['sourceName']for r in old['records']};obsnames={f['properties']['name']for f in obs['features']};capnames={f['properties']['name']for f in caps['features']};assert len(oldnames)==60 and not(oldnames&obsnames or oldnames&capnames or obsnames&capnames);assert obsnames|capnames=={r['sourceName']for r in prev['records']}
