 for f in obs['features']:rows.append({'sourceName':f['properties']['name'],'sourceCoverageStatus':'new_observed_source_contour_estimated_placement','featureId':f['id'],'sourceFile':'source-inferred.geojson','sourceContourIsObserved':True,'sourceMethod':f['properties']['sourceContourType'],'newBatchOutput':True})
