 cov={'schemaVersion':1,'sourceDocumentNameCount':67,'previousObservedSourceContours':60,'additionalObservedSourceContours':5,'observedSourceContoursTotal':65,'separatelyIdentifiedLowConfidenceReconstructedCandidates':2,'sourceNamesWithSomeCandidateGeometry':67,'remainingNamesWithoutAnyCandidateGeometry':[],'remainingLiteralBoundaryInkAmbiguities':['Árpádtető','Petőfi-akna'],'countsDescribeSourceDocumentCoverageOnly':True,'are67VerifiedOrCurrentBoundaries':False,'primaryApprovedInThisBatch':0,'geographicPlacementVerified':False,'claimedAbsoluteAccuracy':None,'records':rows}
