 review={'schemaVersion':1,'reviewDate':'2026-11-14','status':'pass_five_observed_source_contours_plus_two_separate_low_confidence_reconstructions_inferred_only','scope':'Final index of a bounded source-by-source review of the seven previously missing Pecs names. Complete source evidence, manual traces, exact cell corrections and explicit cap inferences are kept distinct.','additionalObservedSourceContourCount':5,'lowConfidenceReconstructedCandidateCount':2,'newCandidateGeometryCount':7,'sourceDocumentCoverage':'65 observed source contours +2 reconstructed candidates; not 67 verified/current boundaries.','firstAndRemainingCohortsChanged':False,'rootRegistryOrExportsChangedByThisBatch':False,'newGeographicModelFitted':False,'primaryApprovedCount':0,'claimedAbsoluteAccuracy':None,'usableForAddressAssignment':False,'reviews':[{'path':n,'sha256':sha(n)}for n in ['pdf-bounded-seven-gap-review.json','independent-kisbalokany-siklosi-name-review.json','independent-manual-islands-review.json','independent-manual-hatched-review.json','independent-final-gap-review.json','remaining-cap-source-quantification.json','independent-cap-review.json']],'coverageAccounting':'source-coverage-accounting.json','observedSourceFile':'source-inferred.geojson','reconstructedSourceFile':'reconstructed-cap-inferred.geojson','localImportSuggestionsNotApplied':['registry-entry.json','registry-entry-caps.json']}
 regs={}
 for filename,source,rid,description in [('registry-entry.json','source-inferred.geojson','pecs-final-five-source-contours-estimated-placement','Five additional whole original quarter contours:two distinct closed raster cells and three independently approved literal manual outer-stroke paths. Placement remains the frozen unverified estimate.'),('registry-entry-caps.json','reconstructed-cap-inferred.geojson','pecs-two-explicit-low-confidence-cap-reconstructions','Two explicitly low-confidence reconstructions with confirmed literal open chains and separately listed uncertain cap segments. Full ring sourceContourIsObserved=false; all inferred edges and alternative chords are retained. Frozen geographic placement is unverified.')]:
  regs[filename]={'id':rid,'path':'data/neighborhoods/sources/municipal-pecs-final-gaps-review/'+source,'sha256':sha(source),'municipality':'Pécs','method':description,'evidenceUrls':['https://logoweb.pecs.hu/download/koncepcio/ITS.pdf'],'license':'Municipal map reuse rights unverified; ODbL for archived OSM calibration evidence.','propertyOverrides':{'boundaryKind':'inferred_area','estimated':True,'canonicalNameIsNeighborhood':False,'usableForAddressAssignment':False,**({'sourceContourIsObserved':False,'reconstructionConfidence':'low'}if source.startswith('reconstructed')else{})},'reviewPath':'data/neighborhoods/sources/municipal-pecs-final-gaps-review/'+('independent-cap-review.json'if source.startswith('reconstructed')else'independent-final-gap-review.json'),'uncertainties':['Geographic placement remains unverified; claimedAbsoluteAccuracy=null, no primary or automatic address approval.','Historic names/geometry do not establish current legal boundaries or municipal-map reuse rights.']+(['The complete rings include explicitly inferred uncertain caps and are not fully observed contours.']if source.startswith('reconstructed')else[]),'rightsStatus':'Public municipal publication; unrestricted map redistribution/reuse licence unverified.','registryEntryAppliedByThisBatch':False}
 return {'source-coverage-accounting.json':cov,'cap-reconstruction-decision.json':decision,'independent-review.json':review,**regs}
